rule "CR_TREND_BEAR_GUARD_001"
salience 100
when
    $f : StockFactorFact()
    eval($f.matches("data_status", "eq", "normal"))
    eval($f.matches("short_term_trend", "eq", "down") || $f.matches("short_term_trend", "eq", "strong_down"))
    eval($f.matches("technical_status", "eq", "bearish"))
then
    $f.addBearishScore(new BigDecimal("55"));
    $f.addRiskScore(new BigDecimal("15"));
    $f.addTriggeredRule("CR_TREND_BEAR_GUARD_001");
    $f.addExplanation("趋势与技术状态同步偏弱，信号偏向防守并提示回撤风险；仅供研究和辅助决策，不构成投资建议。");
end

